// Write entries to the correct connection's master_log
// This is the ONLY node that writes to master_log — all paths lead here
const data = global.get("parat_bridge");
const deliveryStatus = msg.status || "delivered";

msg.payload.forEach(entry => {
    const connectionId = entry.connection_id
        || (msg.connection && msg.connection.id);

    const connection = data.connections.find(c => c.id === connectionId);
    if (!connection) {
        node.warn("Cannot log entry — no connection found for ID: " + connectionId);
        return;
    }

    // Create a clean copy for the log (don't mutate the original)
    const logEntry = Object.assign({}, entry);

    // Remove queue-specific fields that don't belong in the log
    delete logEntry.retryCount;
    delete logEntry.createdAt;

    // Strip binary data from files, keep only metadata
    // (prevents master_log from growing huge with image blobs)
    if (logEntry.files && logEntry.files.length > 0) {
        logEntry.attachments = logEntry.files.map(file => ({
            filename: file.filename || file.name || "unknown",
            size: file.size || (file.blob ? file.blob.length : 0) || 0,
            type: file.filetype || file.type || "unknown"
        }));
        delete logEntry.files;
    }
    if (logEntry.rayvnFileIds) {
        delete logEntry.rayvnFileIds;
    }

    // Set delivery status and timestamp
    logEntry.status = deliveryStatus;
    if (deliveryStatus === "delivered") {
        logEntry.deliveredAt = new Date().toISOString();
        delete logEntry.lastError;
    } else if (deliveryStatus === "failed") {
        logEntry.failedAt = new Date().toISOString();
    }

    // Safety net: double-check for duplicates (should be caught upstream)
    const alreadyExists = connection.master_log.some(e => e.id === logEntry.id);
    if (alreadyExists) {
        node.warn("Duplicate slipped through to Append — entry ID: " + logEntry.id + 
                   ". This suggests a bug in the upstream pipeline.");
        return;
    }

    connection.master_log.push(logEntry);
});

global.set("parat_bridge", data);
return msg;

// Check incoming entries against the connection's existing master_log
// to prevent double-logging (e.g. from race conditions)
const connection = msg.connection;

if (!connection) {
    node.warn("No connection on msg for duplicate check");
    return msg;
}

const data = global.get("parat_bridge");
const conn = data.connections.find(c => c.id === connection.id);
const existingMasterLog = conn ? conn.master_log : [];

// Within a single connection, entry ID is unique
const existingIds = new Set(existingMasterLog.map(e => e.id));

const duplicates = msg.payload.filter(e => existingIds.has(e.id));
msg.payload = msg.payload.filter(e => !existingIds.has(e.id));

if (duplicates.length > 0) {
    node.warn("Duplicate entries removed: " + duplicates.map(d => d.id).join(", "));
}

return msg;
